#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <string>
#include <vector>
struct Edge{int dst; double w;};
struct Graph{int n; std::vector<int> row; std::vector<Edge> e;};
struct Drive{int T; std::vector<std::vector<std::pair<int,double>>> x;};
enum Method{FULL,LAZY,A50,A70,A90,H50_70,H70_90};
struct Result{std::vector<double> v,snap; std::vector<uint8_t> spikes; uint64_t updates=0,edges=0,events=0,full_steps=0,lazy_steps=0,switches=0; double ms=0;};
static Graph graph(int n,double den,uint32_t seed){Graph g;g.n=n;g.row.resize(n+1);std::mt19937 r(seed);std::uniform_real_distribution<double>u(0,1);std::normal_distribution<double>w(0,.08/std::sqrt((double)n));for(int s=0;s<n;s++){g.row[s]=g.e.size();for(int d=0;d<n;d++)if(s!=d&&u(r)<den)g.e.push_back({d,w(r)});}g.row[n]=g.e.size();return g;}
static double activity(int t,int T,int sched){int q=t*4/T;switch(sched){case 0:return q<2?.10:.90;case 1:return q<2?.90:.10;case 2:return (q%2)==0?.10:.90;default:return q<2?.30:.80;}}
static Drive drive(int n,int T,int sched,uint32_t seed){Drive d;d.T=T;d.x.resize(T);std::mt19937 r(seed);std::uniform_real_distribution<double>a(.28,.48);for(int t=0;t<T;t++){int k=(int)std::llround(activity(t,T,sched)*n);std::vector<int>ids(n);for(int i=0;i<n;i++)ids[i]=i;std::shuffle(ids.begin(),ids.end(),r);for(int j=0;j<k;j++)d.x[t].push_back({ids[j],a(r)});std::sort(d.x[t].begin(),d.x[t].end());}return d;}
static const char* nm(Method m){switch(m){case FULL:return"FULL";case LAZY:return"LAZY";case A50:return"A50";case A70:return"A70";case A90:return"A90";case H50_70:return"H50_70";case H70_90:return"H70_90";}return"?";}
static Result run(const Graph&g,const Drive&in,Method m,bool capture){int n=g.n,T=in.T;Result z;z.v.assign(n,0);z.spikes.assign((size_t)n*T,0);if(capture)z.snap.resize((size_t)n*T);std::vector<double>acc(n),dec(T+1,1);for(int i=1;i<=T;i++)dec[i]=dec[i-1]*.9;std::vector<int>mark(n,-1),last(n,0),touched,prev,next;touched.reserve(n);prev.reserve(n);next.reserve(n);bool usefull=false;auto begin=std::chrono::steady_clock::now();for(int t=0;t<T;t++){touched.clear();auto add=[&](int d,double v){if(mark[d]!=t){mark[d]=t;acc[d]=0;touched.push_back(d);}acc[d]+=v;};next.clear();for(int s:prev)for(int k=g.row[s];k<g.row[s+1];k++){auto&e=g.e[k];add(e.dst,e.w);z.edges++;}for(auto&e:in.x[t]){add(e.first,e.second);z.events++;}double frac=(double)touched.size()/n;bool full=(m==FULL);if(m==A50)full=frac>=.50;if(m==A70)full=frac>=.70;if(m==A90)full=frac>=.90;if(m==H50_70){if(!usefull&&frac>=.70)usefull=true;else if(usefull&&frac<=.50)usefull=false;full=usefull;}if(m==H70_90){if(!usefull&&frac>=.90)usefull=true;else if(usefull&&frac<=.70)usefull=false;full=usefull;}if(t>0){bool prior=(m==FULL)||(m==A50?false:m==A70?false:m==A90?false:false);(void)prior;}if(full){z.full_steps++;for(int d=0;d<n;d++){double v=z.v[d];if(last[d]==t-1)v*=.9;else v*=dec[t-last[d]];v+=(mark[d]==t?acc[d]:0);last[d]=t;z.updates++;if(v>=1){v=0;z.spikes[(size_t)t*n+d]=1;next.push_back(d);}z.v[d]=v;}}else{z.lazy_steps++;for(int d:touched){double v=z.v[d]*dec[t-last[d]]+acc[d];last[d]=t;z.updates++;if(v>=1){v=0;z.spikes[(size_t)t*n+d]=1;next.push_back(d);}z.v[d]=v;}}prev.swap(next);if(capture)for(int d=0;d<n;d++)z.snap[(size_t)t*n+d]=z.v[d]*dec[t-last[d]];}for(int d=0;d<n;d++)z.v[d]*=dec[(T-1)-last[d]];z.ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();return z;}
static int mm(const std::vector<uint8_t>&a,const std::vector<uint8_t>&b){int q=0;for(size_t i=0;i<a.size();i++)q+=a[i]!=b[i];return q;}static double err(const std::vector<double>&a,const std::vector<double>&b){double q=0;for(size_t i=0;i<a.size();i++)q=std::max(q,std::abs(a[i]-b[i]));return q;}static double med(std::vector<double>a){std::sort(a.begin(),a.end());return a[a.size()/2];}
int main(){const int N=4096,T=128;double dens[]={.002};uint32_t gs[]={33,44},ss[]={303,404};Method ms[]={FULL,LAZY,A50,A70,A90,H50_70,H70_90};const char*sn[]={"LOW_HIGH","HIGH_LOW","BURST","MID_HIGH"};printf("ENV,gcc=%s,N=%d,T=%d,fp=double,paired_rotating=1\n",__VERSION__,N,T);puts("CHECK,density,gseed,sched,iseed,method,mismatch,maxerr,updates,full_steps,lazy_steps");int checks=0,fail=0;double worst=0;for(double den:dens)for(auto gseed:gs){Graph g=graph(N,den,gseed);for(int sc=0;sc<4;sc++)for(auto seed:ss){Drive d=drive(N,T,sc,seed);Result ref=run(g,d,FULL,true);for(auto m:ms){auto r=run(g,d,m,true);int x=mm(ref.spikes,r.spikes);double e=err(ref.snap,r.snap);checks++;fail+=x||e>1e-12;worst=std::max(worst,e);printf("C,%.4f,%u,%s,%u,%s,%d,%.12g,%llu,%llu,%llu\n",den,gseed,sn[sc],seed,nm(m),x,e,(unsigned long long)r.updates,(unsigned long long)r.full_steps,(unsigned long long)r.lazy_steps);}}}printf("CHECK_SUMMARY,groups=%d,failures=%d,worst_error=%.12g\n",checks,fail,worst);puts("BENCH,density,gseed,sched,iseed,method,median_ms,updates,full_steps,lazy_steps");int rows=0;for(double den:dens)for(auto gseed:gs){Graph g=graph(N,den,gseed);for(int sc=0;sc<4;sc++)for(auto seed:ss){Drive d=drive(N,T,sc,seed);std::vector<std::vector<double>>ts(7);Result last[7];for(int j=0;j<7;j++)run(g,d,ms[j],false);for(int rep=0;rep<7;rep++){int rot=rep%7;for(int j=0;j<7;j++){int i=(j+rot)%7;last[i]=run(g,d,ms[i],false);ts[i].push_back(last[i].ms);}}for(int i=0;i<7;i++){printf("B,%.4f,%u,%s,%u,%s,%.6f,%llu,%llu,%llu\n",den,gseed,sn[sc],seed,nm(ms[i]),med(ts[i]),(unsigned long long)last[i].updates,(unsigned long long)last[i].full_steps,(unsigned long long)last[i].lazy_steps);rows++;}}}printf("BENCH_SUMMARY,rows=%d,repeats=7\n",rows);return fail?3:0;}
